INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10001, "ふっふっふ、これでカヤぴぃとボスを見返してやるです！", "vo_minigame_1004_top_1_000", 1, 2, "vo_minigame_1004", 1000101);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10002, "しりとりでの戦い、お兄さんにも手伝ってもらうです", "vo_minigame_1004_top_1_003", 1, 2, "vo_minigame_1004", 1000201);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10003, "どんなケンカも売られた以上は買うのが喧嘩屋だ！やってやるぜ！", "vo_minigame_1004_top_1_004", 2, 1, "vo_minigame_1004", 1000301);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10004, "石板でしりとりか……イノリのヤツおもしろいこと考えるな", "vo_minigame_1004_top_1_005", 2, 1, "vo_minigame_1004", 1000401);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10005, "しりとりだろうがなんだろうが返り討ちにしてやるぜ", "vo_minigame_1004_top_1_006", 2, 1, "vo_minigame_1004", 1000501);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10006, "ぐもも……（オデ、ハラヘッタ）", "vo_minigame_1004_top_1_007", 3, 2, "vo_minigame_1004", 1000601);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10007, "ぐもももも（シリトリ タノシイ）", "vo_minigame_1004_top_1_008", 3, 2, "vo_minigame_1004", 1000701);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10008, "ぐもももも！（イノリ イイヤツ）", "vo_minigame_1004_top_1_009", 3, 2, "vo_minigame_1004", 1000801);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10009, "カヤぴぃ相手でも手加減しないです", "vo_minigame_1004_top_2_010", 1, 2, "vo_minigame_1004", 1000901);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10009, "上等だ！やるからには本気で来いよな", "vo_minigame_1004_top_2_011", 2, 1, "vo_minigame_1004", 1000902);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10010, "カヤぴぃ、謝るなら今のうちです", "vo_minigame_1004_top_2_012", 1, 2, "vo_minigame_1004", 1001001);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10010, "イノリこそ泣きを入れるなら今のうちだぜ？", "vo_minigame_1004_top_2_013", 2, 1, "vo_minigame_1004", 1001002);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10011, "カヤぴぃ、これからは知性の時代ですよ？", "vo_minigame_1004_top_2_014", 1, 2, "vo_minigame_1004", 1001101);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10011, "待て！オレがバカみたいにいうな！！", "vo_minigame_1004_top_2_015", 2, 1, "vo_minigame_1004", 1001102);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10012, "さあ、あたしたちの力を見せてやるです", "vo_minigame_1004_top_2_016", 1, 1, "vo_minigame_1004", 1001201);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10012, "ぐも！（マカセロ！）", "vo_minigame_1004_top_2_017", 3, 2, "vo_minigame_1004", 1001202);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10013, "よしよし、いいですようまくできたらチョコをあげるです！", "vo_minigame_1004_top_2_018", 1, 1, "vo_minigame_1004", 1001301);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10013, "ぐも！（オデ チョコスキ）", "vo_minigame_1004_top_2_019", 3, 2, "vo_minigame_1004", 1001302);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10014, "なあイノリ……もしかして当初の目的見失ってないよな？", "vo_minigame_1004_top_2_023", 2, 1, "vo_minigame_1004", 1001401);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10014, "もちろん覚えてるですカヤぴぃを倒し我々の知能を証明するです", "vo_minigame_1004_top_2_024", 1, 2, "vo_minigame_1004", 1001402);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10015, "いくらイノリ相手でも勝ちを譲る気はないからな！", "vo_minigame_1004_top_2_025", 2, 1, "vo_minigame_1004", 1001501);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10015, "望むところです手加減はなしですよ", "vo_minigame_1004_top_2_026", 1, 2, "vo_minigame_1004", 1001502);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10016, "へっ、なかなかやるじゃねえか", "vo_minigame_1004_top_2_027", 2, 1, "vo_minigame_1004", 1001601);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10016, "カヤぴぃも思ったよりやるですね！", "vo_minigame_1004_top_2_028", 1, 2, "vo_minigame_1004", 1001602);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10017, "お～い、ドラゴンもどき？", "vo_minigame_1004_top_2_029", 2, 1, "vo_minigame_1004", 1001701);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10017, "ぐもっ！？（ヒッ！）", "vo_minigame_1004_top_2_030", 3, 2, "vo_minigame_1004", 1001702);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10018, "いやあ、あんときは悪かったなはっはっは", "vo_minigame_1004_top_2_031", 2, 1, "vo_minigame_1004", 1001801);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10018, "ぐももも……（かやピィ コワカッタ）", "vo_minigame_1004_top_2_032", 3, 2, "vo_minigame_1004", 1001802);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10019, "お前ってさ……ほんとマヌケな顔してるよな", "vo_minigame_1004_top_2_033", 2, 1, "vo_minigame_1004", 1001901);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10019, "ぐも……（オマエガ イウカ）", "vo_minigame_1004_top_2_034", 3, 2, "vo_minigame_1004", 1001902);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10020, "ぐも……（ハラヘッタ チョコホシイ）", "vo_minigame_1004_top_2_044", 3, 2, "vo_minigame_1004", 1002001);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10020, "なんだ？眠いのか？", "vo_minigame_1004_top_2_045", 2, 1, "vo_minigame_1004", 1002002);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10021, "ぐもも（コイツ……キケン）", "vo_minigame_1004_top_2_046", 3, 2, "vo_minigame_1004", 1002101);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10021, "うん？　なんだ？オレの舎弟にでもなりたいのか？", "vo_minigame_1004_top_2_047", 2, 1, "vo_minigame_1004", 1002102);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10022, "ぐも…（かやピィノウキン）", "vo_minigame_1004_top_2_048", 3, 2, "vo_minigame_1004", 1002201);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10022, "おい、今失礼なこと考えてるだろ？", "vo_minigame_1004_top_2_049", 2, 1, "vo_minigame_1004", 1002202);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10023, "なあ、これいつまで続けるんだ？", "vo_minigame_1004_top_3_058", 2, 1, "vo_minigame_1004", 1002301);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10023, "カヤぴぃが降参するまでです！", "vo_minigame_1004_top_3_059", 1, 2, "vo_minigame_1004", 1002302);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10023, "ぐもも！（コウサンシロ！）", "vo_minigame_1004_top_3_060", 3, 2, "vo_minigame_1004", 1002303);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10024, "ぐも！（イノリ チョコホシイ）", "vo_minigame_1004_top_3_065", 3, 2, "vo_minigame_1004", 1002401);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10024, "しょうがないですね、食べ過ぎはダメですよ", "vo_minigame_1004_top_3_066", 1, 1, "vo_minigame_1004", 1002402);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10024, "土産のチョコ、そうとう気に入ったみたいだな", "vo_minigame_1004_top_3_067", 2, 1, "vo_minigame_1004", 1002403);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10025, "ぐも！（かやピィニハ マケナイ！）", "vo_minigame_1004_top_3_068", 3, 2, "vo_minigame_1004", 1002501);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10025, "お？なんだ？腹でも減ってるのか？", "vo_minigame_1004_top_3_069", 2, 1, "vo_minigame_1004", 1002502);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10025, "……全然話が通じてないです", "vo_minigame_1004_top_3_070", 1, 2, "vo_minigame_1004", 1002503);
